'use strict';
// Product-focused mockup layer: the three analysis studios share one photo flow,
// then return a concrete result that can be used in the rest of Beautify.
const STUDIO_HAIRCUTS=[
 {id:'cascade',name:'Dégradé cascade',pos:'atlas-tl',length:'Long',textures:['Raides','Ondulés'],care:'Entretien modéré',reason:'Garde la longueur et apporte du mouvement autour du visage.',salon:'Long dégradé, mèches souples autour du visage, pointes pleines.'},
 {id:'bob',name:'Carré net',pos:'atlas-tr',length:'Court',textures:['Raides','Ondulés'],care:'Entretien régulier',reason:'Dessine une ligne claire et reste simple à comprendre au salon.',salon:'Carré au niveau du menton, ligne nette, très léger mouvement aux pointes.'},
 {id:'curly-shag',name:'Shag bouclé',pos:'atlas-bl',length:'Mi-long',textures:['Bouclés','Crépus'],care:'Entretien modéré',reason:'Répartit le volume tout en laissant la texture naturelle visible.',salon:'Dégradé progressif sur cheveux bouclés, volume conservé, contour souple.'},
 {id:'pixie-soft',name:'Pixie texturé',pos:'atlas-br',length:'Très court',textures:['Raides','Ondulés','Bouclés'],care:'Entretien régulier',reason:'Une option courte avec du mouvement et plusieurs façons de placer le dessus.',salon:'Pixie court sur les côtés, dessus plus long et texturé, contour souple.'}
];
const STUDIO_USES={
 'Vêtements':{title:'À porter près du visage',copy:'Hauts, robes, foulards et vestes : commencez par les couleurs principales de votre palette.',examples:['Ivoire','Framboise','Marine']},
 'Maquillage':{title:'Des teintes cohérentes',copy:'Reliez les lèvres, les yeux et le teint à la famille de couleurs choisie, selon votre envie de maquillage.',examples:['Rose doux','Prune','Taupe']},
 'Cheveux':{title:'Une couleur à discuter au salon',copy:'Repérez les reflets et profondeurs qui s’accordent à votre palette avant de les adapter avec votre coiffeur.',examples:['Moka','Chocolat','Reflet froid']},
 'Accessoires':{title:'Les détails qui relient le look',copy:'Bijoux, lunettes, sacs et chaussures permettent de tester une famille de couleurs sans changer toute la tenue.',examples:['Argent doux','Anthracite','Rose poudré']}
};
const STUDIO_BASE={acc:V['ACC-01'],analysis:V['ANA-10'],reveal:V['ANA-09'],ess2:V['ESS-02'],ess3:V['ESS-03'],premium:V['PRE-01'],makeup:V['MAQ-01'],wardrobe:V['GAR-01']};

function studioEnsure(){
 M.hairGenerations||={used:0,limit:10,reset:studioNextReset()};
 M.colorUse||='Vêtements';M.skinTab||='Analyse';M.hairTab||='Recommandées';
}
function studioNextReset(){const d=new Date();d.setMonth(d.getMonth()+1,1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-01';}
function studioRemaining(){studioEnsure();return Math.max(0,M.hairGenerations.limit-M.hairGenerations.used);}
function studioHairTile(c,large=false){return `<div class="hair-atlas ${c.pos} ${large?'large':''}" role="img" aria-label="${esc(c.name)}, référence sur mannequin sans identité"></div>`;}
function studioHairScore(c){const texture=M.hairProfile?.texture||M.prefs.hair;return (c.textures.includes(texture)?6:0)+(M.hairProfile?.length===c.length?2:0)+(c.id==='cascade'?1:0);}
function studioHairList(recommended=false){const list=STUDIO_HAIRCUTS.slice().sort((a,b)=>recommended?studioHairScore(b)-studioHairScore(a):a.name.localeCompare(b.name));return `<div class="studio-hair-grid">${list.map((c,i)=>A(`${studioHairTile(c)}<span>${recommended&&i===0?'<small class="studio-badge">Notre choix</small>':''}<strong>${esc(c.name)}</strong><small>${esc(c.length)}, ${esc(c.care)}</small></span>`,'haircut-open',{id:c.id},'studio-hair-card')).join('')}</div>`;}
function studioCard(title,copy,action,domain,iconName){return A(`<span class="studio-icon">${icon(iconName)}</span><span><small>${esc(domain)}</small><strong>${esc(title)}</strong><em>${esc(copy)}</em></span>${icon('chev')}`,action,{domain},'glass studio-entry');}
function studioStrip(){return `<section class="studio-strip"><div class="between"><div><span class="eyebrow">Mes analyses</span><h2>Trois façons de commencer</h2></div>${B('Tout voir','ANA-01','text-button')}</div><div class="studio-mini-grid">${B(`${icon('hair')}<strong>Ma coupe</strong><small>${studioRemaining()}/10 essais</small>`,'HAI-01','glass studio-mini')}${B(`${icon('palette')}<strong>Mes couleurs</strong><small>4 usages</small>`,'COL-01','glass studio-mini')}${B(`${icon('leaf')}<strong>Ma peau</strong><small>Ma routine</small>`,'PEA-01','glass studio-mini')}</div></section>`;}
function studioLatest(domain){return M.analyses.filter(x=>x.domain===domain).at(-1);}
function studioPalette(){return PALETTES[M.colorProfile?.palette||M.context.palette||'palette-cool']||PALETTES['palette-cool'];}
function studioSkinTraits(){return M.skinProfile?.traits||['Hydratation à soutenir','Confort à observer','Éclat irrégulier'];}

studioEnsure();

V['ACC-01']=()=>{const actions=dailyActions(),next=M.events.filter(e=>e.date>=DATE()&&e.status!=='done').sort((a,b)=>a.date.localeCompare(b.date))[0];return head(M.profile.name?'Bonjour '+esc(M.profile.name):'Un moment pour vous',dateText(DATE()))+studioStrip()+sec('Pour aujourd’hui','ACC-03','Ma journée')+(actions.length?actions.slice(0,2).map(taskRow).join(''):intent('Une idée en quelques minutes','Cheveux, couleurs, maquillage, peau ou tenue','catalog',{time:'5 minutes'},'sparkles'))+`<div class="quick-links">${B(icon('calendar')+' Ma semaine','ACC-02','secondary')}${B(icon('sun')+' Mes routines','ROU-01','secondary')}</div>`+(next?sec('Ma prochaine occasion','EVE-01')+eventCard(next):intent('Préparer une occasion','Réunir coiffure, maquillage et tenue','new-event',{},'calendar'))+sec('Une inspiration pour moi','DEC-01')+grid(recommendations().slice(0,2))+moreActions(B('Mon journal et mes habitudes','PRO-01','secondary')+B('Toutes mes occasions','EVE-01','secondary mt')+B('Mes messages','ACC-04','secondary mt'),'Retrouver mon espace');};

V['ANA-01']=()=>head('Pour moi','Analyser un besoin, puis agir avec un résultat concret.')+`<div class="studio-stack">${studioCard('Les coupes qui me correspondent','Forme du visage, texture, longueur et entretien.','studio-analysis','Cheveux','hair')}${studioCard('Les couleurs qui me mettent en valeur','Vêtements, maquillage, cheveux et accessoires.','studio-analysis','Colorimétrie','palette')}${studioCard('Comprendre les besoins de ma peau','Photo, réponses et routine matin/soir adaptée.','studio-analysis','Peau','leaf')}</div>`+(M.draft.status!=='complete'&&(M.draft.photo||Object.keys(M.draft.answers||{}).length)?row('Reprendre mon analyse',M.draft.domain,M.draft.phase,'spark'):'')+sec('Mes derniers résultats')+(['Cheveux','Colorimétrie','Peau'].map(d=>{const r=studioLatest(d);return r?reportCard(r):row(d,'Aucune analyse enregistrée','ANA-02',DOMAINS.find(x=>x[0]===d)?.[1]||'spark');}).join(''))+moreActions(B('Tous mes comptes rendus','ANA-12','secondary')+B('Mes photos et données','PRF-07','secondary mt'))+note('Mockup : les résultats montrent le fonctionnement prévu. Aucun moteur réel n’est exécuté ici.');

V['ANA-02']=()=>head('Que souhaitez-vous analyser ?','Chaque analyse possède son propre résultat.')+progress(1,5)+`<div class="studio-stack compact">${studioCard('Trouver une coupe','Recommandations et essai sur votre photo.','studio-analysis','Cheveux','hair')}${studioCard('Trouver mes couleurs','Une palette utilisable dans tous vos looks.','studio-analysis','Colorimétrie','palette')}${studioCard('Construire ma routine','Les besoins observés et vos ressentis.','studio-analysis','Peau','leaf')}</div>`+moreActions(A('Explorer aussi le maquillage','studio-analysis',{domain:'Maquillage'},'secondary')+A('Explorer aussi mon style','studio-analysis',{domain:'Garde-robe'},'secondary mt'),'Autres envies')+B('Découvrir sans analyse','DEC-01','text-button mt');

V['ANA-03']=()=>{const copy={Cheveux:['Pour recommander des coupes','La photo sert à observer les proportions visibles du visage et la chevelure. Vos réponses précisent la texture, la longueur et l’entretien souhaité.'],Colorimétrie:['Pour construire votre palette','La lumière et l’écran peuvent modifier les couleurs. Vous pourrez corriger le résultat et choisir librement une autre palette.'],Peau:['Pour préparer votre routine','L’analyse décrit des signes visibles et vos ressentis. Elle ne remplace pas un diagnostic ni un avis professionnel.']}[M.draft.domain]||['Pour personnaliser vos pistes','La photo reste facultative et vos réponses peuvent être corrigées.'];return head('Avant de commencer',copy[0])+panel(`<h3>${esc(M.draft.domain)}</h3>${P(copy[1])}${P('Vous pourrez supprimer la photo et le compte rendu depuis votre espace de données.')}`)+form('consent',check('consent','J’ai compris l’usage de cette photo dans la démonstration.',M.draft.consent),'Continuer')+B('Revenir à mes analyses','ANA-01','secondary mt');};

V['ANA-04']=()=>head('Ajouter une photo',M.draft.domain==='Peau'?'Visage propre, lumière naturelle si possible.':'Visage de face, lumière uniforme, sans filtre.')+progress(2,5)+panel(`${icon('image','glow-icon xl')}<h2>Une photo nette et récente</h2>${P('Elle permet de présenter le parcours de recommandation prévu.')}`)+A('Choisir une photo','file-pick',{purpose:'analysis'})+A('Utiliser la photo d’exemple','sample-photo',{},'secondary mt')+moreActions(B('Prendre une photo — aperçu','ANA-05','secondary')+note('Mockup : aucune caractéristique n’est réellement calculée.'),'Conseils de prise de vue');

const studioOldAnalysisFields=analysisFields;
analysisFields=function(){const a=M.draft.answers||{},p=M.prefs,d=M.draft.domain;if(d==='Cheveux')return select('texture','Texture naturelle',['Raides','Ondulés','Bouclés','Crépus','Je ne sais pas'],a.texture||p.hair)+select('length','Longueur actuelle',['Très courte','Courte','Mi-longue','Longue'],a.length||'Mi-longue')+select('change','Changement souhaité',['Discret','Visible','Radical'],a.change||'Visible')+select('fringe','Une frange ?',['Pourquoi pas','Oui','Non'],a.fringe||'Pourquoi pas')+select('care','Entretien accepté',['Très simple','Modéré','Régulier'],a.care||'Modéré');if(d==='Colorimétrie')return select('colorGoal','Je veux utiliser mes couleurs pour',['Tout mon look','Mes vêtements','Mon maquillage','Mes cheveux'],a.colorGoal||'Tout mon look')+select('contrast','Contraste préféré',['Doux','Moyen','Marqué','Je ne sais pas'],a.contrast||'Je ne sais pas')+field('colors','Les couleurs que j’aime déjà',a.colors||'')+area('avoidColors','Les couleurs que je porte moins — facultatif',a.avoidColors||'');if(d==='Peau')return select('afterWash','Après le nettoyage, ma peau semble',['Confortable','Elle tire','Elle brille vite','Cela dépend'],a.afterWash||'Cela dépend')+select('sensitivity','Ma peau réagit facilement',['Souvent','Parfois','Rarement','Je ne sais pas'],a.sensitivity||'Je ne sais pas')+select('skinGoal','Ma priorité',['Confort','Hydratation','Éclat','Imperfections','Routine simple'],a.skinGoal||'Routine simple')+area('skin','Ce que j’utilise déjà — facultatif',a.skin||'');return studioOldAnalysisFields();};

V['HAI-01']=()=>{studioEnsure();const tab=M.hairTab||'Recommandées';return head('Hair Studio','Trouver une coupe, puis choisir librement.')+`<div class="quota-card"><div><span>${icon('spark')}</span><strong>${studioRemaining()} essais disponibles</strong><small>sur 10 ce mois-ci, renouvellement ${dateText(M.hairGenerations.reset)}</small></div><span class="quota-number">${studioRemaining()}</span></div>`+(!M.hairProfile?intent('Analyser mon visage et mes cheveux','Recevoir des coupes classées et expliquées','studio-analysis',{domain:'Cheveux'},'sparkles'):panel(`<span class="eyebrow">Mon profil coupe</span><h2>${esc(M.hairProfile.shape)}</h2>${P(esc(M.hairProfile.texture)+', '+esc(M.hairProfile.care))}${A('Corriger mon profil','hair-profile-edit',{},'text-button')}`))+chips(['Recommandées','Toutes','Couleurs'],'hairTab',tab)+(tab==='Couleurs'?panel(`<h2>Mes couleurs de cheveux</h2>${P('Retrouvez les nuances proposées par votre profil couleur, puis adaptez-les avec votre coiffeur.')}${swatchGrid(studioPalette().colors.slice(0,5))}${A('Ouvrir Color Studio','open-color-use',{use:'Cheveux'})}`):(tab==='Recommandées'?sec('Les meilleures options pour moi')+studioHairList(true)+note('Classement selon la forme observée, la texture et vos préférences. Vous gardez le dernier mot.'):sec('Choisir ma propre coupe')+studioHairList(false)+note('Ces références utilisent un mannequin sans identité.')))+A('Mes simulations enregistrées','saved-hair-sims',{},'secondary mt');};

V['COL-01']=()=>{const p=studioPalette(),use=M.colorUse||'Vêtements',u=STUDIO_USES[use];return head('Color Studio','Une palette, quatre façons de l’utiliser.')+(!M.colorProfile?intent('Analyser mes couleurs','Créer une palette depuis une photo et mes préférences','studio-analysis',{domain:'Colorimétrie'},'sparkles'):panel(`<span class="eyebrow">Mon profil couleur</span><h2>${esc(M.colorProfile.name)}</h2>${P('Une base modifiable, jamais une règle à suivre.')}${A('Revoir mon analyse','studio-analysis',{domain:'Colorimétrie'},'text-button')}`))+swatchGrid(p.colors.slice(0,5))+chips(Object.keys(STUDIO_USES),'colorUse',use)+`<section class="color-use-card"><span class="eyebrow">${esc(use)}</span><h2>${esc(u.title)}</h2>${P(esc(u.copy))}<div class="color-example-list">${u.examples.map(x=>`<span>${esc(x)}</span>`).join('')}</div></section>`+A(use==='Vêtements'?'Trouver une tenue':use==='Maquillage'?'Voir les maquillages':use==='Cheveux'?'Voir les couleurs cheveux':'Garder cette palette',use==='Vêtements'?'catalog':use==='Maquillage'?'go-makeup':use==='Cheveux'?'go-hair-color':'save',{domain:use==='Vêtements'?'Garde-robe':undefined,type:use==='Vêtements'?'Look':undefined,id:p.mood==='Fraîches'?'palette-cool':p.mood==='Neutres'?'palette-neutral':'palette'})+moreActions(A('Choisir une autre famille','color-family',{},'secondary')+note('La lumière, l’écran et les matières changent la perception d’une couleur.'))};

V['PEA-01']=()=>{const tab=M.skinTab||'Analyse',routines=M.routines.filter(r=>r.domain==='Peau');return head('Skin Studio','Comprendre, construire, ajuster.')+chips(['Analyse','Matin','Soir','Suivi'],'skinTab',tab)+(tab==='Analyse'?(!M.skinProfile?intent('Analyser ma peau','Photo, ressentis et habitudes actuelles','studio-analysis',{domain:'Peau'},'sparkles'):`<section class="skin-profile-card"><span class="eyebrow">Mon dernier bilan</span><h2>Les besoins à observer</h2><div class="skin-traits">${studioSkinTraits().map((x,i)=>`<div><span>${icon(i===0?'drop':i===1?'heart':'spark')}</span><strong>${esc(x)}</strong></div>`).join('')}</div>${A('Refaire ou corriger mon analyse','studio-analysis',{domain:'Peau'},'secondary')}</section>`)+note('Les signes visibles et vos réponses orientent la routine. Aucun diagnostic médical.'):tab==='Suivi'?row('Mon journal de peau','Photos, ressentis et observations','PRO-01','bars')+row('Ajouter une observation','Ce qui a changé ou non','PRO-03','leaf'):`${sec('Ma routine '+tab.toLowerCase())}${routines.filter(r=>r.moment===tab).map(r=>row(r.name,r.steps.length+' gestes, '+r.frequency,'ROU-02','sun',{key:'routine',value:r.id})).join('')||empty('Aucune routine pour ce moment','Commencez avec un modèle, puis adaptez chaque geste.')} ${A('Créer ou adapter une routine','new-routine')}`);};

V['MAQ-01']=()=>panel(`<span class="eyebrow">Depuis Color Studio</span><h2>${esc(studioPalette().mood)}</h2>${P('Retrouvez les familles de teintes proposées pour les yeux et les lèvres.')}${A('Voir mes couleurs maquillage','open-color-use',{use:'Maquillage'},'secondary')}`)+STUDIO_BASE.makeup();
V['GAR-01']=()=>panel(`<span class="eyebrow">Depuis Color Studio</span><h2>Ma palette dans mon dressing</h2>${P('Appliquez vos couleurs aux hauts, bas, robes et accessoires.')}${A('Voir mes couleurs vêtements','open-color-use',{use:'Vêtements'},'secondary')}`)+STUDIO_BASE.wardrobe();

function studioResultView(r){if(!r)return STUDIO_BASE.analysis();if(r.domain==='Cheveux')return head('Mes coupes recommandées',dateText(r.date))+panel(`<span class="eyebrow">Profil pris en compte</span><h2>${esc(M.hairProfile?.shape||'Préférences cheveux')}</h2>${P(esc(M.hairProfile?.texture||M.prefs.hair)+', '+esc(M.hairProfile?.care||'Entretien modéré'))}`)+studioHairList(true)+A('Ouvrir Hair Studio','studio-result-open',{domain:'Cheveux'});if(r.domain==='Colorimétrie'){const p=studioPalette();return head('Ma palette personnelle',dateText(r.date))+panel(`<span class="eyebrow">Profil couleur</span><h2>${esc(M.colorProfile?.name||p.mood)}</h2>${P('À appliquer aux vêtements, au maquillage, aux cheveux et aux accessoires.')}`)+swatchGrid(p.colors.slice(0,5))+A('Utiliser ma palette','studio-result-open',{domain:'Colorimétrie'});}if(r.domain==='Peau')return head('Mon bilan de peau',dateText(r.date))+panel(`<span class="eyebrow">À partir de la photo et de vos réponses</span><h2>Trois repères pour ma routine</h2>`)+`<div class="skin-traits">${studioSkinTraits().map(x=>`<div>${icon('leaf')}<strong>${esc(x)}</strong></div>`).join('')}</div>`+A('Construire ma routine','studio-result-open',{domain:'Peau'})+note('Ce bilan ne constitue pas un diagnostic médical.');return STUDIO_BASE.analysis();}
V['ANA-10']=()=>studioResultView(report());
V['ANA-09']=()=>{const r=report();if(!r||!['Cheveux','Colorimétrie','Peau'].includes(r.domain))return STUDIO_BASE.reveal();return head('Votre analyse est prête',r.domain)+panel(`${icon(DOMAINS.find(x=>x[0]===r.domain)?.[1]||'spark','glow-icon xl')}<h2>${r.domain==='Cheveux'?'Vos coupes sont classées':r.domain==='Colorimétrie'?'Votre palette est prête':'Votre routine peut commencer'}</h2>${P('Vous pouvez corriger les réponses ou explorer directement le résultat.')}`)+B('Voir mon résultat','ANA-10')+A('Corriger mes réponses','edit-analysis',{},'text-button mt');};

V['ESS-02']=()=>M.haircutDraft?head('Votre coupe se prépare','Une génération sera comptée seulement si le résultat aboutit.')+studioHairTile(STUDIO_HAIRCUTS.find(x=>x.id===M.haircutDraft.haircut),true)+panel(`${icon('spark','glow-icon xl')}<h2>${esc(STUDIO_HAIRCUTS.find(x=>x.id===M.haircutDraft.haircut)?.name||'Votre coupe')}</h2>${P(studioRemaining()+' essais encore disponibles avant cette génération.')}`)+A('Afficher ma simulation','finish-haircut'):STUDIO_BASE.ess2();
V['ESS-03']=()=>{const x=M.simulations.find(x=>x.id===M.context.simulation),cut=STUDIO_HAIRCUTS.find(c=>c.id===x?.haircut);if(!cut)return STUDIO_BASE.ess3();return head('Ma simulation',cut.name)+`<div class="comparison studio-comparison"><div>${x.source?imageFor(x.source,'','Photo de départ'):panel(P('Photo retirée'))}<h3>Avant</h3></div><div>${studioHairTile(cut,true)}<h3>Coupe choisie</h3></div></div>`+note('Mockup : la seconde image représente la référence de coupe. Le produit final transformerait uniquement les cheveux.')+panel(`<span class="eyebrow">À montrer au salon</span><h2>${esc(cut.name)}</h2>${P(esc(cut.salon))}`)+A(M.saved.includes(x.id)?'Simulation enregistrée':'Garder cette simulation','save',{id:x.id})+A('Choisir une autre coupe','hair-more',{},'secondary mt')+A('Voir mes '+studioRemaining()+' essais restants','hair-more',{},'text-button mt');};

V['PRE-01']=()=>head('Beautify Premium','Vos analyses et vos choix, réunis.')+`<section class="glass premium-value"><span class="eyebrow">Inclus chaque mois</span><h2>10 simulations<br><span class="accent">de coupes</span></h2><p>Des recommandations classées, votre palette dans tous les univers et une routine de peau adaptable.</p>${B('Voir Hair Studio','HAI-01','secondary')}</section>`+`<div class="offer-comparison"><div><span>Découverte</span><p>Explorer les contenus, enregistrer ses idées et consulter les modèles.</p></div><div><span>Premium</span><p>10 générations de coupes, analyses personnelles, historique et organisation complète.</p></div></div>`+`<fieldset class="billing"><legend>Mon rythme</legend>${['monthly','yearly'].map(v=>A(`<strong>${v==='yearly'?'Annuel':'Mensuel'}</strong><span>${v==='yearly'?'59,99 € / an':'9,99 € / mois'}</span><small>${v==='yearly'?'12 mois, hypothèse à tester':'Un mois, hypothèse à tester'}</small>`,'offer',{value:v,pressed:M.subscription.offer===v},M.subscription.offer===v?'selected':'')).join('')}</fieldset>`+B('Choisir Premium — démo','PRE-02')+A('Continuer en découverte','premium-return',{},'text-button mt')+note('Offre et prix fictifs. Aucun paiement réel dans ce mockup.');

Object.assign(ACTIONS,{
 'studio-analysis':d=>{M.draft={...clone(initial().draft),domain:d.domain,phase:'ANA-03',answers:{},status:'draft'};clearDrafts('analysis-answers');go('ANA-03');},
 'studio-result-open':d=>go(({Cheveux:'HAI-01',Colorimétrie:'COL-01',Peau:'PEA-01'})[d.domain]||'ANA-01'),
 'open-color-use':d=>{M.colorUse=d.use;go('COL-01');},
 'go-makeup':()=>go('MAQ-01'),
 'go-hair-color':()=>{M.hairTab='Couleurs';go('HAI-01');},
 'color-family':()=>modal('Choisir une famille',Object.entries(PALETTES).map(([id,p])=>A(`<span><strong>${esc(p.mood)}</strong><small>${p.colors.slice(0,3).map(x=>esc(x[0])).join(', ')}</small></span>`,'choose-color-family',{id},'glass list-row')).join('')),
 'choose-color-family':d=>{M.colorProfile={name:PALETTES[d.id].mood,palette:d.id};M.context.palette=d.id;closeModal();render();toast('Palette mise à jour.');},
 'haircut-open':d=>{const c=STUDIO_HAIRCUTS.find(x=>x.id===d.id);if(!c)return;M.haircutSelected=c.id;modal(c.name,studioHairTile(c,true)+P(c.reason)+`<div class="cut-meta"><span>${esc(c.length)}</span><span>${esc(c.care)}</span></div>`+P('<strong>Pour le salon :</strong> '+esc(c.salon))+A('Essayer cette coupe sur moi','haircut-simulate',{id:c.id})+A('Retour aux coupes','close',{},'text-button mt'));},
 'haircut-simulate':d=>{const c=STUDIO_HAIRCUTS.find(x=>x.id===d.id);if(!c)return;if(!studioRemaining()){closeModal();M.context.returnTo='HAI-01';go('PRE-01');return;}M.haircutSelected=c.id;modal('Préparer ma simulation',P('Cette simulation utilisera 1 de vos '+studioRemaining()+' générations disponibles.')+(M.simulationPhoto?imageFor(M.simulationPhoto,'article-photo','Photo choisie')+P('Votre photo est prête.'):P('Ajoutez une photo de face ou utilisez l’exemple du mockup.'))+A('Choisir ma photo','file-pick',{purpose:'simulation'},'secondary')+A('Utiliser la photo d’exemple','haircut-example',{},'secondary mt')+A('Générer cette coupe','haircut-generate-confirm',{id:c.id},'mt'));},
 'haircut-example':()=>{M.simulationPhoto='selfie';render();closeModal();ACTIONS['haircut-simulate']({id:M.haircutSelected});},
 'haircut-generate-confirm':d=>{if(!M.simulationPhoto){toast('Choisissez une photo avant de générer la coupe.');return;}closeModal();M.haircutDraft={id:uid('haircut'),haircut:d.id,source:M.simulationPhoto};go('ESS-02',{context:{haircut:d.id}});},
 'finish-haircut':()=>{const d=M.haircutDraft,c=STUDIO_HAIRCUTS.find(x=>x.id===d?.haircut);if(!d||!c){go('HAI-01');return;}if(['error','offline'].includes(M.scenario)){M.scenario='normal';toast('La génération a échoué. Aucun essai n’a été utilisé.');return;}if(!studioRemaining()){M.context.returnTo='HAI-01';go('PRE-01');return;}let x=M.simulations.find(x=>x.id===d.id);if(!x){M.hairGenerations.used++;x={id:d.id,name:'Simulation, '+c.name,source:d.source,haircut:c.id,look:'layers',image:'layers',type:'Simulation',domain:'Cheveux',date:DATE(),desc:'Simulation de coupe dans le mockup.'};M.simulations.push(x);}M.haircutDraft=null;go('ESS-03',{replace:true,context:{simulation:x.id,haircut:c.id}});},
 'hair-more':()=>{M.hairTab='Toutes';go('HAI-01');},
 'saved-hair-sims':()=>{M.savedTab='Tous';M.savedType='Simulation';go('SAV-01');},
 'hair-profile-edit':()=>modal('Corriger mon profil',form('hair-profile',select('shape','Forme du visage',['Ovale','Rond','Allongé','Carré','Cœur','Je ne sais pas'],M.hairProfile?.shape||'Je ne sais pas')+select('texture','Texture',['Raides','Ondulés','Bouclés','Crépus','Je ne sais pas'],M.hairProfile?.texture||M.prefs.hair)+select('care','Entretien',['Très simple','Modéré','Régulier'],M.hairProfile?.care||'Modéré'),'Mettre à jour')),
});
F['hair-profile']=d=>{M.hairProfile={...M.hairProfile,shape:d.shape,texture:d.texture,care:d.care};M.prefs.hair=d.texture;closeModal();render();toast('Profil mis à jour.');};

const studioFinish=ACTIONS['finish-analysis'];
ACTIONS['finish-analysis']=()=>{const domain=M.draft.domain,answers=clone(M.draft.answers||{});studioFinish();if(M.draft.status!=='complete')return;if(domain==='Cheveux'){M.hairProfile={shape:M.draft.photo?'Ovale — à confirmer':'Préférences renseignées',texture:answers.texture||M.prefs.hair,care:answers.care||'Modéré'};}else if(domain==='Colorimétrie'){const id=answers.contrast==='Doux'?'palette-cool':answers.contrast==='Marqué'?'palette':'palette-neutral';M.colorProfile={name:PALETTES[id].mood,palette:id};M.context.palette=id;}else if(domain==='Peau'){M.skinProfile={traits:[answers.afterWash==='Elle tire'?'Hydratation à soutenir':'Hydratation à observer',answers.sensitivity==='Souvent'?'Sensibilité signalée':'Confort à suivre',answers.skinGoal==='Éclat'?'Éclat à accompagner':'Routine à simplifier'],goal:answers.skinGoal||'Routine simple'};}persist();};
